package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.Loan;
import jakarta.persistence.Column;
import jakarta.persistence.Embedded;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.LocalDate;
import java.util.UUID;

@Entity
@Table(name = "loan")
class LoanJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    @Embedded
    private CreditCheckEmbeddable creditCheck;

    private LocalDate returnedAt;

    protected LoanJpaEntity() {
    }

    static LoanJpaEntity from(Loan loan) {
        LoanJpaEntity entity = new LoanJpaEntity();
        entity.id = loan.getId();
        entity.bookId = loan.getBookId();
        entity.memberId = loan.getMemberId();
        entity.loanedAt = loan.getLoanedAt();
        entity.dueAt = loan.getDueAt();
        entity.creditCheck = CreditCheckEmbeddable.from(loan.getCreditCheck());
        entity.returnedAt = loan.getReturnedAt().orElse(null);
        return entity;
    }

    Loan toDomain() {
        return Loan.reconstitute(id, bookId, memberId, loanedAt, dueAt, creditCheck.toDomain(), returnedAt);
    }
}
