package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements LoadLoanPort, SaveLoanPort {

    private final LoanJpaRepository loanJpaRepository;

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(LoanJpaEntity::toDomain);
    }

    @Override
    public int countActiveLoans(UUID memberId) {
        return Math.toIntExact(loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId));
    }

    @Override
    public List<Loan> loadActiveLoans(UUID memberId, int page, int size) {
        // 같은 날짜의 대출끼리도 페이지 경계가 흔들리지 않도록 id 로 한 번 더 정렬한다.
        PageRequest pageRequest = PageRequest.of(page, size, Sort.by("loanedAt", "id"));
        if (pageRequest.getOffset() > Integer.MAX_VALUE) {
            return List.of();
        }
        return loanJpaRepository.findByMemberIdAndReturnedAtIsNull(memberId, pageRequest).stream()
                .map(LoanJpaEntity::toDomain)
                .toList();
    }

    @Override
    public List<Loan> loadLoanHistory(UUID memberId) {
        return loanJpaRepository.findByMemberIdOrderByLoanedAtDescIdDesc(memberId).stream()
                .map(LoanJpaEntity::toDomain)
                .toList();
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(LoanJpaEntity.from(loan));
    }
}
