package com.example.lending.domain;

import java.time.YearMonth;
import java.util.List;
import java.util.Objects;

// 한 달 동안의 대출·반납 통계. 대출 건수는 대출일, 반납·연체 건수와 연체료 합계는 반납일이 그 달인 대출로 센다.
public record MonthlyLoanStatistics(YearMonth month, long loanCount, long returnCount, long overdueCount,
                                    long lateFeeTotal) {

    public MonthlyLoanStatistics {
        Objects.requireNonNull(month, "month");
    }

    public static MonthlyLoanStatistics of(YearMonth month, List<Loan> loanedInMonth, List<Loan> returnedInMonth) {
        long loanCount = loanedInMonth.stream()
                .filter(loan -> YearMonth.from(loan.getLoanedAt()).equals(month))
                .count();
        List<Loan> returned = returnedInMonth.stream()
                .filter(loan -> loan.getReturnedAt().map(YearMonth::from).filter(month::equals).isPresent())
                .toList();
        long overdueCount = returned.stream().filter(loan -> loan.lateFee() > 0).count();
        long lateFeeTotal = returned.stream().mapToLong(Loan::lateFee).sum();
        return new MonthlyLoanStatistics(month, loanCount, returned.size(), overdueCount, lateFeeTotal);
    }
}
